<?php require 'header.php';require_login();$s=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC');$s->execute([user()['id']]);$orders=$s->fetchAll();$status=['pending'=>'รอดำเนินการ','paid'=>'ชำระแล้ว','shipping'=>'กำลังจัดส่ง','completed'=>'สำเร็จ','cancelled'=>'ยกเลิก'];?><div class="container"><h1>ประวัติคำสั่งซื้อ</h1><?php if(!$orders):?><div class="empty">ยังไม่มีคำสั่งซื้อ</div><?php else:?><div class="table-wrap"><table><tr><th>เลขที่</th><th>วันที่</th><th>ยอดรวม</th><th>สถานะ</th><th>รายละเอียด</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=h($o['created_at'])?></td><td>฿<?=money($o['total'])?></td><td><?=h($status[$o['status']]??$o['status'])?></td><td><a style="color:var(--orange)" href="order_detail.php?id=<?=$o['id']?>">ดูรายการ</a></td></tr><?php endforeach;?></table></div><?php endif;?></div><?php require 'footer.php';?>
